  putt:    function () { tn(1200, 600, 0.05, 'square', 0.08, 0, 0, 0, ['bandpass', 1500, 3]); nz(0.03, 0.25, 'highpass', 2500); tn(300, 0, 0.05, 'sine', 0.2); },
