  splash:  function () { nz(0.45, 0.32, 'lowpass', 2200, 300); tn(700, 1200, 0.06, 'sine', 0.1, 0.12); tn(900, 1500, 0.05, 'sine', 0.08, 0.2); },
  plop:    function () { tn(500, 140, 0.18, 'sine', 0.35); tn(1320, 0, 0.15, 'triangle', 0.08, 0.12); tn(1760, 0, 0.2, 'triangle', 0.08, 0.2); },
