function sfx(n) { if (save.audio === 2) return; try { SFX[n] && SFX[n](); } catch (e) {} }
function music(key) {
  bgmWant = key;
  if (save.audio !== 0) { if (bgmNow) bgmNow.pause(); return; }
  var a = bgm[key]; if (!a) { a = bgm[key] = new Audio('bgm-' + key + '.mp3'); a.loop = true; a.onerror = function () { a.dead = true; }; }
  if (a.dead) return;
  a.volume = key === 'map' ? 0.45 : 0.3;
  if (bgmNow && bgmNow !== a) bgmNow.pause();
  bgmNow = a; if (a.paused) { var p = a.play(); if (p && p.catch) p.catch(function () {}); }
}
function audioIcon() { return ['🎵', '🔊', '🔇'][save.audio || 0]; }
function cycleAudio(btn) { save.audio = ((save.audio || 0) + 1) % 3; store(); out(); if (save.audio === 0) music(bgmWant || 'map'); else if (bgmNow) bgmNow.pause(); btn.textContent = audioIcon(); if (save.audio === 1) sfx('tap'); }
document.addEventListener('pointerdown', function () { ac(); if (save.audio === 0 && bgmWant && (!bgmNow || bgmNow.paused)) music(bgmWant); }, true);
